-- Optional fixture for SYNONYM and MATERIALIZED_VIEW exports.
-- Requires privileges to create private synonyms and materialized views.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP MATERIALIZED VIEW OC_EMPLOYEE_MV';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-12003, -942) THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP SYNONYM OC_EMP_SYNONYM';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1434 THEN RAISE; END IF;
END;
/

CREATE OR REPLACE SYNONYM OC_EMP_SYNONYM FOR OC_EMPLOYEES;

CREATE MATERIALIZED VIEW OC_EMPLOYEE_MV
BUILD IMMEDIATE
REFRESH COMPLETE ON DEMAND
AS
SELECT D.DEPARTMENT_NAME,
       COUNT(*) AS EMPLOYEE_COUNT,
       SUM(E.SALARY) AS TOTAL_SALARY
  FROM OC_DEPARTMENTS D,
       OC_EMPLOYEES E
 WHERE E.DEPARTMENT_ID = D.DEPARTMENT_ID
 GROUP BY D.DEPARTMENT_NAME;

COMMENT ON MATERIALIZED VIEW OC_EMPLOYEE_MV IS 'Optional oracode materialized view fixture';

PROMPT Optional synonym/materialized view fixture loaded
